spec.expr:
( sum by (stream, node) (
  label_replace(
    directory_file_count{base="/streams",stream=~"$stream",type=~".*/input/[^/]+"},
    "node",
    "$1",
    "type",
    "^(.+)/input/[^/]+$"
  )
) > 0 ) or ( sum by (stream, node) (
  directory_buffer_files{
    base="/streams",
    stream=~"$stream",
    type="collector"
  }
)) > 0
